useEffect(()=>{const p=location.pathname.split('/')[1];if(p)setPage(p);const c=localStorage.getItem('exora-client')||'';refresh(c).catch(()=>refresh());const shortcut=(e:KeyboardEvent)=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();(document.querySelector('[aria-label="Search workspace"]') as HTMLInputElement)?.focus()}};window.addEventListener('keydown',shortcut);const pop=()=>setPage(location.pathname.split('/')[1]||'overview');window.addEventListener('popstate',pop);return()=>{window.removeEventListener('popstate',pop);window.removeEventListener('keydown',shortcut)}},[]);
