const records=data?.records||[],byKind=(k:string)=>records.filter((r:any)=>r.kind===k),client=data?.client,brand=byKind('BrandKit')[0],modules=data?.modules||[],current=modules.find((m:any)=>m.key===page),canEdit=data?.user?.role!=='reviewer',canReview=['admin','reviewer'].includes(data?.user?.role),disabled=client?.settings?.disabled_modules||[],pending=byKind('Approval').filter((r:any)=>r.status==='awaiting_review'),tasks=byKind('Task'),assets=byKind('Asset'),searchResults=search?records.filter((r:any)=>(r.title+' '+r.kind+' '+JSON.stringify(r.data)).toLowerCase().includes(search.toLowerCase())).slice(0,12):[];
