const upload=async(file:File)=>{setBusy(true);try{const form=new FormData();form.set('client_id',clientId);form.set('file',file);const r=await fetch('/api/upload',{method:'POST',body:form});const d=await r.json();if(!r.ok)throw new Error(d.error);await refresh();notify('File added to your library');return d}catch(e:any){notify(e.message,true)}finally{setBusy(false)}};
