{page==='04-hooks'&&<><div className="notice compact"><Lightbulb size={18}/><span>Choose a hook to carry into the content step. Scores are editorial guidance, not performance predictions.</span></div>{byKind('Idea').map((r:any)=><section className="panel section" key={r.id}><div className="panel-title"><div><span className="eyebrow">IDEA / {date(r.created_at)}</span><h2>{r.title}</h2></div><button className="text-button" onClick={()=>view(r)}>Details <ArrowUpRight size={14}/></button></div><div className="hook-grid">{r.data.hooks?.map((h:any,i:number)=><article className={`hook-card ${r.data.selected_hook===i?'chosen':''}`} key={i}><div><span className="eyebrow">HOOK {i+1}</span><b className="hook-score">{h.score??'—'}<small>/100</small></b></div><h3>“{h.text}”</h3><span className="tag">{h.formula}</span>{h.verdict&&<span className="tag">{h.verdict}{h.weakest?' · weakest: '+h.weakest:''}</span>}<p>{h.rationale}</p>{h.scored_by&&<p className="form-note">Scored by {h.scored_by}</p>}<button className={r.data.selected_hook===i?'button primary':'button'} disabled={busy||!canEdit} onClick={()=>act({action:'choose-hook',id:r.id,index:i},'Hook selected').catch(()=>{})}>{r.data.selected_hook===i?<Check size={15}/>:<Plus size={15}/>} {r.data.selected_hook===i?'Selected hook':'Choose this hook'}</button></article>)}</div></section>)}{!byKind('Idea').length&&<Empty title="A strong start changes everything" icon={Lightbulb}>Generate three hooks from your latest campaign and select the one to develop.</Empty>}</>}
