{page==='managing'&&<><div className="section-title"><div className="tab-row"><button className="selected">Team board</button></div><div className="action-row">{canEdit&&button('Retainer invoice',()=>setModal({type:'invoice'}),false,FileText)}{canEdit&&button('Add task',()=>newRecord('Task'),true)}</div></div><div className="kanban">{[{key:'todo',name:'To do'},{key:'in_progress',name:'In progress'},{key:'done',name:'Done'}].map(col=><section className="kanban-column" key={col.key}><div className="kanban-title"><span className={'kanban-dot '+col.key}/><h3>{col.name}</h3><span>{tasks.filter((t:any)=>(t.status==='draft'?'todo':t.status)===col.key).length}</span></div>{tasks.filter((t:any)=>(t.status==='draft'?'todo':t.status)===col.key).map((t:any)=><article className="task-card" key={t.id}><span className={`priority ${t.data.priority}`}>{t.data.priority}</span><h3 onClick={()=>view(t)}>{t.title}</h3><p>{t.data.body}</p><div className="task-meta"><span>{t.data.owner}</span><span>{date(t.data.due_date)}</span></div><select aria-label={'Status for '+t.title} value={col.key} disabled={!canEdit||busy} onChange={e=>act({action:'task-status',id:t.id,status:e.target.value},'Task moved').catch(()=>{})}><option value="todo">To do</option><option value="in_progress">In progress</option><option value="done">Done</option></select></article>)}</section>)}</div></>}
